#Requires -Version 7.6
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$fixtureNames = @('grace-ops-1049-cosmos', 'grace-ops-1049-azurite')
$existing = @(docker ps -a --format '{{.Names}}')
if ($LASTEXITCODE -ne 0) { throw 'Docker inventory failed.' }
foreach ($fixtureName in $fixtureNames) {
    if ($existing -contains $fixtureName) { throw "Fixture name already exists: $fixtureName. Preserve it and inspect before retrying." }
}
$listeners = @(Get-NetTCPConnection -State Listen)
if (@($listeners | Where-Object LocalPort -In @(18081, 11000)).Count -gt 0) { throw 'An assigned loopback port is occupied.' }
docker run -d --pull never --name grace-ops-1049-cosmos -p 127.0.0.1:18081:8081 6ce44ed4ac69 --protocol https
if ($LASTEXITCODE -ne 0) { throw 'Owned Cosmos startup failed.' }
docker run -d --pull never --name grace-ops-1049-azurite -p 127.0.0.1:11000:10000 76b8127d608f azurite-blob --blobHost 0.0.0.0 --skipApiVersionCheck
if ($LASTEXITCODE -ne 0) { throw 'Owned Azurite startup failed.' }
# Readiness is setup, outside every measurement window. No shared Aspire cleanup is called.
$deadline = [DateTimeOffset]::UtcNow.AddSeconds(60)
do {
    $cosmosStatus = & curl.exe --silent --insecure --max-time 2 --output NUL --write-out '%{http_code}' https://127.0.0.1:18081/
    $blobStatus = & curl.exe --silent --max-time 2 --output NUL --write-out '%{http_code}' http://127.0.0.1:11000/devstoreaccount1
    if ($cosmosStatus -in @('200', '401') -and $blobStatus -eq '400') { break }
    if ([DateTimeOffset]::UtcNow -gt $deadline) { throw "Fixture readiness deadline: Cosmos=$cosmosStatus Blob=$blobStatus" }
    Start-Sleep -Seconds 1
} while ($true)
Write-Output "READY: Cosmos=$cosmosStatus Blob=$blobStatus"
docker inspect grace-ops-1049-cosmos grace-ops-1049-azurite | Set-Content -LiteralPath "$PSScriptRoot/provider-inspect.json"

#Requires -Version 7.6
param([Parameter(Mandatory)][string] $RepositoryRoot, [switch] $SkipBuild)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$RepositoryRoot = (Resolve-Path -LiteralPath $RepositoryRoot).Path
$expectedBase = 'd16a9693035d375a6d9eac39419b1abbab1ead49'
git -C $RepositoryRoot diff --exit-code $expectedBase -- src global.json Directory.Packages.props
if ($LASTEXITCODE -ne 0) { throw 'The executable producer inputs differ from the pinned base.' }
if (-not $SkipBuild) {
    dotnet build "$RepositoryRoot/src/Grace.Server/Grace.Server.fsproj" --configuration Release --nologo -v quiet -p:CopyLocalLockFileAssemblies=true 2>&1 | Tee-Object -FilePath "$PSScriptRoot/build.log"
    if ($LASTEXITCODE -ne 0) { throw 'Pinned Grace Server build failed.' }
}
$binaryPath = "$RepositoryRoot/src/Grace.Server/bin/Release/net10.0"
$references = @('#I "' + $binaryPath.Replace('\','/') + '"')
$references += Get-ChildItem -LiteralPath $binaryPath -Filter '*.dll' | Where-Object Name -ne 'FSharp.Core.dll' | ForEach-Object {
    try { [Reflection.AssemblyName]::GetAssemblyName($_.FullName) | Out-Null; '#r "' + $_.Name + '"' } catch {}
}
$references += '#load "Experiment.fsx"'
$references | Set-Content -LiteralPath "$PSScriptRoot/Load.fsx"
dotnet fsi "$PSScriptRoot/Load.fsx" 2>&1 | Tee-Object -FilePath "$PSScriptRoot/run.log"
if ($LASTEXITCODE -ne 0) { throw 'TextContent measurement experiment failed.' }

#Requires -Version 7.6
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
# The only provider resources this experiment owns. Keep containers and logs for inspection.
foreach ($fixtureName in @('grace-ops-1049-cosmos', 'grace-ops-1049-azurite')) {
    docker logs $fixtureName *> "$PSScriptRoot/$fixtureName.log"
    if ($LASTEXITCODE -ne 0) { throw "Cannot capture owned fixture logs: $fixtureName" }
    docker stop $fixtureName
    if ($LASTEXITCODE -ne 0) { throw "Cannot stop owned fixture: $fixtureName" }
}

